dimension_discovery_query:
query ActiveCustomDimensionDefinitionsQuery {
  appFoundationsActiveCustomDimensionDefinitions(
    first: 20
    after: null
    last: null
    before: null
  ) {
    edges {
      node {
        ...CustomDimensionDefinitionAttributes
      }
    }
  }
}
fragment CustomDimensionDefinitionAttributes on AppFoundations_CustomDimensionDefinition {
  id
  label
  active
}

dimension_values_query:
query CustomDimensionsValuesQuery {
  appFoundationsActiveCustomDimensionValues(
    first: 20,
    filters: { definitionId: "1000000002", parentId: null }
  ) {
    edges {
      node {
        id
        definitionId
        fullyQualifiedLabel
      }
    }
  }
}

custom_field_definitions_query:
query GetCustomFieldDefinitions($cursor: String) {
  appFoundationsCustomFieldDefinitions(
    filters: { active: true }
    first: 50
    after: $cursor
  ) {
    edges {
      node {
        id
        legacyID
        legacyIDV2
        label
        dataType
        required
        active
        colorCode
        entityVersion
        createdSource
        dropDownOptions { id value active order }
        associations {
          associatedEntity
          associationCondition
          active
          allowedOperations
          subAssociations { associatedEntity active allowedOperations }
        }
      }
    }
    pageInfo { hasNextPage hasPreviousPage startCursor endCursor }
  }
}

custom_field_create_definition_mutation:
mutation CreateCustomFieldDefinition($input: AppFoundations_CustomFieldDefinitionCreateInput!) {
  appFoundationsCreateCustomFieldDefinition(input: $input) {
    id
    legacyIDV2
    label
    dataType
    required
    active
    dropDownOptions { id value active order }
    associations {
      associatedEntity
      associationCondition
      active
      allowedOperations
      subAssociations { associatedEntity active allowedOperations }
    }
  }
}

custom_field_update_definition_mutation:
mutation UpdateCustomFieldDefinition($input: AppFoundations_CustomFieldDefinitionUpdateInput!) {
  appFoundationsUpdateCustomFieldDefinition(input: $input) {
    id
    legacyIDV2
    label
    dataType
    active
    required
    associations {
      associatedEntity
      associationCondition
      active
      allowedOperations
    }
  }
}

sales_tax_calculate_mutation:
mutation CalculateTax($input: IndirectTax_TaxCalculationInput!) {
  indirectTaxCalculateSaleTransactionTax(input: $input) {
    ... on IndirectTax_TaxCalculationPayload {
      taxCalculation {
        id
        transactionDate
        subject {
          customer { id }
          taxExemption
        }
        shipping {
          shipFromAddress { streetAddressLine1 }
          shipToAddress { streetAddressLine1 }
          shippingFee { value }
          taxAmount { value }
        }
        lineItems {
          nodes {
            numberOfUnits
            totalPriceExcludingTaxes { value }
            productVariantTaxability { classificationCode }
            taxAmount { value }
            taxDetails {
              taxAmount { value }
              taxableAmount { value }
              taxExemptAmount { value }
              ratePercentageApplied { ... on IndirectTax_RatePercentage { rate } }
              taxRate { name taxRate { taxRateReferenceId } }
            }
          }
        }
        taxTotals {
          totalTaxAmountExcludingShipping { value }
          aggregatedTaxesExcludingShippingByRate {
            taxableAmount { value }
            taxAmount { value }
            ratePercentageApplied { ... on IndirectTax_RatePercentage { rate } }
            taxRate { name taxRate { taxRateReferenceId } }
          }
        }
      }
    }
  }
}

